CREATE TABLE IF NOT EXISTS user_voices (uid TEXT NOT NULL, speaker_id TEXT NOT NULL, name TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'preset', dialect TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (uid)); ALTER TABLE user_voices ENABLE ROW LEVEL SECURITY; CREATE POLICY user_voice_isolation ON user_voices USING (uid = current_setting('request.jwt.claims.uid', true)); COMMENT ON TABLE user_voices IS '每用户1条「我的音色」覆盖式绑定';
